parents = {"a": [], "b": ["a"], "c": ["b"], "d": ["b"], "e": ["c"]}
tips = {"main": "e", "feature": "b", "other": "d", "hotfix": "c"}

def ancestors(commit):
    seen, stack = set(), [commit]
    while stack:
        current = stack.pop()
        if current not in seen:
            seen.add(current)
            stack.extend(parents[current])
    return seen

def merge_kind(into, other):
    if tips[other] in ancestors(tips[into]):
        return "already up to date"
    if tips[into] in ancestors(tips[other]):
        return "fast-forward"
    return "merge commit"

print(merge_kind("main", "feature"))
print(merge_kind("feature", "main"))
print(merge_kind("main", "other"))
print(merge_kind("hotfix", "main"))
print(len(ancestors(tips["main"]) - ancestors(tips["feature"])))
